param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-native-digits-aliased-revalidation-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$property=[Globalization.NumberFormatInfo].GetProperty('NativeDigits')
function Decode($Encoded){if([object]::ReferenceEquals($Encoded,$null)){return ,$null};$a=[string[]]::new($Encoded.Count);for($i=0;$i -lt $a.Length;$i++){if(-not [object]::ReferenceEquals($Encoded[$i],$null)){$a[$i]=-join [char[]][int[]]$Encoded[$i]}};return ,$a}
function Normalize($Array){if([object]::ReferenceEquals($Array,$null)){return ,$null};$values=[Collections.Generic.List[object]]::new();foreach($s in $Array){if([object]::ReferenceEquals($s,$null)){$values.Add($null)}else{$values.Add([int[]][char[]]$s)}};return ,$values.ToArray()}
function Digits($N){$a=[string[]]$property.GetValue($N);return ,(Normalize $a)}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$rows=[Collections.Generic.List[object]]::new()
for($family=0;$family -lt $plan.families.Count;$family++){foreach($position in $plan.positions){foreach($mutation in $plan.mutations){foreach($mode in $plan.modes){
 $inputDigits=Decode $plan.families[$family];$saved=$inputDigits[$position];$original=[Globalization.NumberFormatInfo]::new();$property.SetValue($original,$inputDigits);$view=[Globalization.NumberFormatInfo]::ReadOnly($original);$copy=[Globalization.NumberFormatInfo]$original.Clone();switch($mode){'mutable'{$target=$original};'readonly'{$target=$view};'clone'{$target=$copy}}
 switch($mutation){'null'{$inputDigits.SetValue($null,[int]$position)};'empty'{$inputDigits[$position]=''};'two'{$inputDigits[$position]='00'};'high'{$inputDigits[$position]=[string][char]0xd800};'wrong'{$inputDigits[$position]=[string](($position+1)%10)};'private'{$inputDigits[$position]=[string][char](0xe100+$position)};'alternate'{$inputDigits[$position]=[string][char](0x660+$position)}}
 $corrupt=Normalize $inputDigits;$before=Digits $target;try{$property.SetValue($target,$inputDigits);$first=[ordered]@{ok=$true}}catch{$first=Failure $_};$afterFirst=Digits $target;$originalFirst=Digits $original;$copyFirst=Digits $copy;$viewFirst=Digits $view
 $inputDigits[$position]=$saved;$repaired=Digits $target;try{$property.SetValue($target,$inputDigits);$second=[ordered]@{ok=$true}}catch{$second=Failure $_};$afterRepair=Digits $target
 $replacement=Decode $plan.families[(($family+1)%$plan.families.Count)];try{$property.SetValue($target,$replacement);$third=[ordered]@{ok=$true}}catch{$third=Failure $_};$afterReplace=Digits $target
 $inputDigits[0]='old!';$replacement[1]='new!';$afterOldNew=Digits $target;$originalFinal=Digits $original;$copyFinal=Digits $copy;$viewFinal=Digits $view;$getter=[string[]]$property.GetValue($target);$getter[2]='getter!';$afterGetter=Digits $target
 $rows.Add([ordered]@{family=$family;position=$position;mutation=$mutation;mode=$mode;corrupt=$corrupt;before=$before;first=$first;afterFirst=$afterFirst;originalFirst=$originalFirst;copyFirst=$copyFirst;viewFirst=$viewFirst;repaired=$repaired;second=$second;afterRepair=$afterRepair;third=$third;afterReplace=$afterReplace;afterOldNew=$afterOldNew;originalFinal=$originalFinal;copyFinal=$copyFinal;viewFinal=$viewFinal;afterGetter=$afterGetter;targetReadOnly=$target.IsReadOnly;copyReadOnly=$copy.IsReadOnly;viewReadOnly=$view.IsReadOnly})
}}}}
if($rows.Count -ne 504){throw 'Wrong aliased revalidation matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification='SELECTED_ALIASED_NATIVE_DIGIT_REVALIDATION_AND_REPLACEMENT_ONLY; UNICODE_FORMATTING_CULTURES_METADATA_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 26 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS aliased NativeDigits revalidation: 504 cases'
